{


}

sub Select
	{
	my ($SQLStr, $Cnt, $sql, @Values, $self, $Col, @Flds, $i);

	$self = shift;

	$SQLStr = "SELECT * FROM " . $self->Name . ' ' . $self->Where;
	print "Record.pm \t $SQLStr\n";
	$sql = AXSQL->new(ControlObject => $self->ControlObject, SQLString => $SQLStr);

	#construct a hash using the metadata and the data from the actual table
	$self->Fields = 0;
	@Values = $sql->Fetch();
	if ($sql->Rowcount >= 1)
		{
		$self->Populated = 1;
		}
	else
		{
		$self->Populated = 0;
		}
	#Get field Names
	$sql = AXSQL->new(ControlObject => $self->ControlObject, SQLString => "show fields from '" . $self->Name . "'");
	@Flds = $sql->fetch();
	# Construct the hash
	for ($i..$#Flds)
		{
		if ($self->Populate == 0)
			{
			$self->Fields->{$Flds[$i]} = $Values[$i];
			}
		Else
			{
			$self->Fields->{$Flds[$i]} = ' ';
			}
		}

	#Get the primary key fields		
	$self->Keys = ();
	$sql = AXSQL->new(ControlObject => $self->ControlObject, SQLString => "SELECT column_name FROM information_schema.`key_column_usage` WHERE table_name = '" . $self->name . "' order by ordinal_position");
	while (($Col) = $sql.fetch())
		{
		push $self->Keys, $Col;
		}

	$Cnt = $self->Fields;
	$self->FieldCount = $Cnt;
	$self->Changed = -1;
	}
1;
